 {id:0,name:"entry",exported:true,parameters:[0],slots:["reference"],returnType:"general",entry:0,blocks:[{id:0,instructions:[{kind:"load",id:0,slot:0,...span},{kind:"call-indirect",id:1,target:1,callee:0,arguments:[],...span}],terminator:{kind:"return",value:1,...span}}]},
